BEGIN;
GRANT USAGE ON SCHEMA public,auth TO authenticated,anon;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO authenticated;
CREATE FUNCTION correction_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END; $$;
CREATE FUNCTION correction_reject(command text,label text,code text DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN IF code IS NOT NULL AND SQLSTATE<>code THEN RAISE EXCEPTION 'FAIL wrong error % for %: %',SQLSTATE,label,SQLERRM; END IF; RAISE NOTICE 'PASS rejected: % (%)',label,SQLERRM; RETURN; END; RAISE EXCEPTION 'FAIL accepted: %',label; END; $$;
INSERT INTO auth.users(id,email) VALUES('ca000000-0000-4000-8000-000000000001','correction-direction@example.test'),('ca000000-0000-4000-8000-000000000002','correction-operator@example.test'),('ca000000-0000-4000-8000-000000000003','correction-client@example.test');
INSERT INTO staff_users(id,auth_id,nom,email,role,must_change_password) VALUES
