 VALUES('ca300000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','en_preparation',1,ARRAY['RECEIPT-1'],'[{"number":"RECEIPT-1"}]','[{"dimL":40,"dimW":30,"dimH":20,"poids":4}]',40,30,20,4,'autorise',now(),'[{"dimL":30,"dimW":20,"dimH":10,"poids":3}]',30,20,10,3,0,now(),1);
