GRANT ALL ON observed TO authenticated;
SELECT correction_assert(NOT has_function_privilege('anon','correct_colis_task(uuid,text,jsonb,timestamptz,text)','EXECUTE'),'anonymous cannot correct a dossier');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','ca000000-0000-4000-8000-000000000003',true);
SELECT correction_reject($q$SELECT correct_colis_task('ca300000-0000-4000-8000-000000000001','reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',now(),'Correction pesée')$q$,'client cannot correct operational measures','42501');
SELECT set_config('request.jwt.claim.sub','ca000000-0000-4000-8000-000000000002',true);
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{}',NULL,'Correction pesée') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'CAS cannot be omitted','40001');
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{}','2000-01-01','Correction pesée') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'stale version rejected before mutation','40001');
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[],"statut":"paye"}',updated_at,'Correction pesée') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'unknown fields cannot smuggle status changes','22023');
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":0}]}',updated_at,'Correction pesée') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'zero measures rejected','22023');
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5},{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction pesée') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'correction cannot add a received carton','22023');
INSERT INTO observed SELECT to_jsonb(c),correct_colis_task(id,'reception','{"boxes":[{"dimL":"40","dimW":30,"dimH":20,"poids":"4.0"}]}',updated_at,'Relecture sans changement') FROM colis c WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT correction_assert((SELECT result->>'changed'='false' AND before_row=result->'colis' FROM observed),'numeric-equivalent correction is a true no-op including timestamp');
