RESET ROLE;
UPDATE staff_permissions SET perm_colis_revenir_arriere=false WHERE staff_id='ca100000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction pesée') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'measurement permission alone is insufficient','42501');
RESET ROLE;
UPDATE staff_permissions SET perm_colis_revenir_arriere=true,perm_colis_mesurer=false WHERE staff_id='ca100000-0000-4000-8000-000000000002';
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction pesée') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'correction permission alone is insufficient','42501');
SELECT correction_reject($q$UPDATE colis SET consent_request_version=8 WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'direct version forgery rejected','42501');
RESET ROLE;
UPDATE staff_permissions SET perm_colis_mesurer=true WHERE staff_id='ca100000-0000-4000-8000-000000000002';
UPDATE colis SET devis_total=100,devis_transport=60,devis_om=20,devis_omr=5,devis_tva=15,devis_snapshot='{"inputs":{"marker":"first quote"},"amounts":{"total":100}}',devis_brouillon=false WHERE id='ca300000-0000-4000-8000-000000000001';
UPDATE colis SET statut='devis_envoye',payplug_payment_id='pay_task_old',payplug_payment_url='https://example.test/retired' WHERE id='ca300000-0000-4000-8000-000000000001';
