SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction poids') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'hosted URL without provider ID cannot be withdrawn through direct RPC','22023');
SELECT correction_assert((SELECT (correct_colis_task(id,'reception',jsonb_build_object('boxes',dims_par_colis),updated_at,'Sans changement')->>'changed')::boolean=false FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'no-op preserves unidentified hosted URL without withdrawal');
RESET ROLE;
UPDATE colis SET payplug_payment_id='pay_task_old' WHERE id='ca300000-0000-4000-8000-000000000001';
INSERT INTO payment_intents(colis_id,quote_version,provider_id,payment_url,amount_cents,status) SELECT id,quote_version,'pay_task_old',payplug_payment_url,10000,'pending' FROM colis WHERE id='ca300000-0000-4000-8000-000000000001';
TRUNCATE observed;
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction poids') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'active provider link blocks correction until cancellation proof','22023');
SELECT correction_assert((SELECT (correct_colis_task(id,'reception',jsonb_build_object('boxes',dims_par_colis),updated_at,'Sans changement')->>'changed')::boolean=false FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'no-op retains active payment without provider cancellation');
SELECT correction_reject($q$SELECT save_preparation_measurements(id,final_packages,updated_at,preparation_composition_version) FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'legacy measurement save cannot withdraw quote bypassing correction','22023');
