RESET ROLE;
UPDATE payment_intents SET status='creating' WHERE provider_id='pay_task_old';
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction poids') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'payment creation race blocks correction','40001');
RESET ROLE;
-- This failed intent is no longer linked by the dossier: its hosted provider resource still needs proof.
UPDATE payment_intents SET status='failed' WHERE provider_id='pay_task_old';
UPDATE colis SET payplug_payment_id=NULL,payplug_payment_url=NULL WHERE id='ca300000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction poids') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'failed orphan intent with provider ID still requires cancellation proof','22023');
RESET ROLE;
UPDATE colis SET payplug_payment_id='pay_task_old',payplug_payment_url='https://example.test/retired' WHERE id='ca300000-0000-4000-8000-000000000001';
UPDATE payment_intents SET status='pending',provider_is_live=false WHERE provider_id='pay_task_old';
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT correction_assert(NOT has_function_privilege('authenticated','record_payplug_cancellation(uuid,text,jsonb)','EXECUTE'),'browser cannot forge provider cancellation proof');
SELECT correction_reject($q$SELECT record_payplug_cancellation(colis_id,provider_id,jsonb_build_object('object','payment','id',provider_id,'is_paid',true,'failure',jsonb_build_object('code','aborted'),'currency','EUR','amount',amount_cents,'is_live',false,'metadata',jsonb_build_object('colis_id',colis_id,'intent_id',id,'quote_version',quote_version))) FROM payment_intents WHERE provider_id='pay_task_old'$q$,'paid provider resource is never cancellation evidence','22023');
SELECT correction_reject($q$SELECT record_payplug_cancellation(colis_id,provider_id,jsonb_build_object('object','payment','id',provider_id,'is_paid',false,'failure',jsonb_build_object('code','aborted'),'currency','EUR','amount',amount_cents+1,'is_live',false,'metadata',jsonb_build_object('colis_id',colis_id,'intent_id',id,'quote_version',quote_version))) FROM payment_intents WHERE provider_id='pay_task_old'$q$,'wrong provider amount rejected','22023');
SELECT correction_reject($q$SELECT record_payplug_cancellation(colis_id,provider_id,jsonb_build_object('object','payment','id',provider_id,'is_paid',false,'failure',jsonb_build_object('code','aborted'),'currency','EUR','amount',amount_cents,'is_live',true,'metadata',jsonb_build_object('colis_id',colis_id,'intent_id',id,'quote_version',quote_version))) FROM payment_intents WHERE provider_id='pay_task_old'$q$,'wrong provider mode rejected','22023');
SELECT correction_reject($q$SELECT record_payplug_cancellation(colis_id,provider_id,jsonb_build_object('object','payment','id',provider_id,'is_paid',false,'failure',jsonb_build_object('code','aborted'),'currency','EUR','amount',amount_cents,'amount_refunded',1,'is_live',false,'metadata',jsonb_build_object('colis_id',colis_id,'intent_id',id,'quote_version',quote_version))) FROM payment_intents WHERE provider_id='pay_task_old'$q$,'refunded provider resource requires reconciliation','22023');
SELECT record_payplug_cancellation(colis_id,provider_id,jsonb_build_object('object','payment','id',provider_id,'is_paid',false,'failure',jsonb_build_object('code','aborted'),'currency','EUR','amount',amount_cents,'is_live',false,'metadata',jsonb_build_object('colis_id',colis_id,'intent_id',id,'quote_version',quote_version))) FROM payment_intents WHERE provider_id='pay_task_old';
SELECT set_config('request.jwt.claim.role','authenticated',true);
SET LOCAL ROLE authenticated;
INSERT INTO observed SELECT to_jsonb(c),correct_colis_task(id,'reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":5}]}',updated_at,'Correction du poids à réception') FROM colis c WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT correction_assert((SELECT result->>'changed'='true' AND result->'invalidated' ? 'devis' AND result->'invalidated' ? 'paiement' FROM observed),'receipt correction reports dependent quote and payment withdrawal');
SELECT correction_assert((SELECT c.poids=5 AND c.feu_vert='autorise' AND c.feu_vert_date=(o.before_row->>'feu_vert_date')::timestamptz AND c.statut='en_preparation' AND c.consent_request_version=0 AND c.preparation_composition_version=0 AND c.final_measurements_version=0 AND c.fin_p=3 AND c.final_packages=o.before_row->'final_packages' FROM colis c,observed o WHERE c.id='ca300000-0000-4000-8000-000000000001'),'simple receipt weight preserves agreement and certified preparation');
SELECT correction_assert((SELECT devis_total IS NULL AND devis_brouillon AND payplug_payment_id IS NULL AND payplug_payment_url IS NULL FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'withdrawn quote and payment URL unavailable');
SELECT correction_assert((SELECT status='superseded' FROM payment_intents WHERE provider_id='pay_task_old'),'previous PayPlug intent superseded');
SELECT correction_assert((SELECT count(*)=1 FROM quote_versions WHERE colis_id='ca300000-0000-4000-8000-000000000001' AND snapshot#>>'{inputs,marker}'='first quote'),'first quote snapshot preserved once');
SELECT correction_assert((SELECT before_data->>'poids'='4.00' OR (before_data->>'poids')::numeric=4 FROM audit_actions WHERE action='correction_reception'),'correction records old measured weight');
SELECT correction_assert((SELECT (after_data->>'poids')::numeric=5 AND user_id='ca000000-0000-4000-8000-000000000002' FROM audit_actions WHERE action='correction_reception'),'correction records new values and actor');
SELECT correction_reject($q$SELECT correct_colis_task('ca300000-0000-4000-8000-000000000001','reception','{"boxes":[{"dimL":40,"dimW":30,"dimH":20,"poids":6}]}',(SELECT (before_row->>'updated_at')::timestamptz FROM observed),'Autre collègue même version')$q$,'second correction on the same opened version loses CAS','40001');
RESET ROLE;
SELECT correction_assert((SELECT count(*)=1 FROM factures f JOIN original_factures o ON to_jsonb(f)=to_jsonb(o)),'validated invoice unchanged by measurements correction');
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT correction_reject($q$SELECT confirm_payplug_payment('pay_task_old','ca300000-0000-4000-8000-000000000001',(SELECT quote_version FROM payment_intents WHERE provider_id='pay_task_old'),10000,'EUR')$q$,'old provider payment cannot pay corrected dossier','22023');
SELECT set_config('request.jwt.claim.role','authenticated',true);
UPDATE colis SET devis_total=120,devis_transport=70,devis_snapshot='{"inputs":{"marker":"second quote"},"amounts":{"total":120}}' WHERE id='ca300000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT correct_colis_task(id,'preparation','{"boxes":[{"dimL":30,"dimW":20,"dimH":10,"poids":2},{"dimL":20,"dimW":20,"dimH":10,"poids":3}]}',updated_at,'Correction des colis préparés') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT correction_assert((SELECT outgoing_parcel_count=2 AND fin_p=5 AND poids=5 AND nb_colis=1 AND final_measurements_version=preparation_composition_version AND feu_vert='autorise' FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'two prepared units remain distinct from one received carton');
SELECT correction_assert((SELECT count(*)=2 FROM quote_versions WHERE colis_id='ca300000-0000-4000-8000-000000000001'),'two successive corrected quotes remain in history');
SELECT correction_assert(EXISTS(SELECT 1 FROM staff_work_actions WHERE colis_id='ca300000-0000-4000-8000-000000000001' AND kind='quote' AND state<>'done'),'quote task reprojected after correction');
SELECT correction_assert(NOT EXISTS(SELECT 1 FROM messages WHERE colis_id='ca300000-0000-4000-8000-000000000001'),'measure corrections send no message and create no client decision');
SELECT correction_assert(NOT EXISTS(SELECT 1 FROM notifications WHERE colis_id='ca300000-0000-4000-8000-000000000001'),'measure corrections send no notification');
RESET ROLE;
-- Reopening the quote alone preserves physical inputs and reviewed invoices.
UPDATE colis SET devis_total=130,devis_transport=80,devis_snapshot='{"inputs":{"marker":"third quote"},"amounts":{"total":130}}' WHERE id='ca300000-0000-4000-8000-000000000001';
TRUNCATE observed;
SET LOCAL ROLE authenticated;
INSERT INTO observed SELECT to_jsonb(c),correct_colis_task(id,'devis','{}',updated_at,'Modifier les frais du devis') FROM colis c WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT correction_assert((SELECT result->>'changed'='true' AND result->'invalidated'='["devis"]'::jsonb AND result#>'{colis,final_packages}'=before_row->'final_packages' AND result#>'{colis,dims_par_colis}'=before_row->'dims_par_colis' AND result#>>'{colis,feu_vert}'='autorise' FROM observed),'quote-only reopening invalidates quote without changing physical measurements or consent');
SELECT correction_assert((SELECT count(*)=3 FROM quote_versions WHERE colis_id='ca300000-0000-4000-8000-000000000001'),'quote-only reopening preserves its prior version too');
SELECT correction_assert((SELECT (correct_colis_task(id,'devis','{}',updated_at,'Relire le brouillon')->>'changed')::boolean=false FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'already withdrawn quote is a no-op');
SELECT correction_assert((SELECT user_nom IS NOT NULL AND length(user_nom)>0 FROM audit_actions WHERE action='correction_devis'),'audit exposes a readable actor for correction');
RESET ROLE;
-- A combined request contains metadata; callbacks compare composition, not all JSON.
SELECT set_config('expedile.revert','allowed',true);
UPDATE colis SET statut='attente_feu_vert',feu_vert='en_attente' WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT set_config('expedile.revert','',true);
INSERT INTO messages(colis_id,type,texte,statut,canal,template,telegram_msg_id,request_snapshot)
 SELECT id,'staff','Demande combinée historique','envoye','telegram','demande_feu_vert','OLD-COMBINED',jsonb_build_object('trackings',trackings,'trackings_detail',trackings_detail,'nb_colis',nb_colis,'invoice_requested',true) FROM colis WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT telegram_client_decision('ca300000-0000-4000-8000-000000000001','approve','CHAT-CORRECTION','OLD-COMBINED');
SELECT correction_assert((SELECT feu_vert='autorise' FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'combined request metadata no longer blocks valid Telegram agreement');
SELECT set_config('request.jwt.claim.role','authenticated',true);
INSERT INTO notification_outbox(message_id,client_id,colis_id,quote_version,canal,status,idempotency_key)
 SELECT m.id,c.client_id,c.id,c.quote_version,'email','manual','OLD-REMINDER' FROM messages m JOIN colis c ON c.id=m.colis_id WHERE m.telegram_msg_id='OLD-COMBINED';
CREATE TEMP TABLE before_consent AS SELECT to_jsonb(c) row,(SELECT count(*) FROM messages WHERE colis_id=c.id) messages,(SELECT count(*) FROM notifications WHERE colis_id=c.id) notifications FROM colis c WHERE id='ca300000-0000-4000-8000-000000000001';
GRANT SELECT ON before_consent TO authenticated;
SET LOCAL ROLE authenticated;
SELECT correct_colis_task(id,'accord','{}',updated_at,'Demander un nouvel accord client') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT correction_assert((SELECT statut='mesure' AND feu_vert='en_attente' AND feu_vert_date IS NULL AND attente_client_date IS NULL AND demande_feu_vert_envoyee_at IS NULL AND consent_request_version=1 AND final_packages=b.row->'final_packages' AND dims_par_colis=b.row->'dims_par_colis' FROM colis c,before_consent b WHERE c.id='ca300000-0000-4000-8000-000000000001'),'new agreement generation preserves all physical measurements but clears previous decision');
SELECT correction_assert((SELECT (SELECT count(*) FROM messages WHERE colis_id='ca300000-0000-4000-8000-000000000001')=messages AND (SELECT count(*) FROM notifications WHERE colis_id='ca300000-0000-4000-8000-000000000001')=notifications FROM before_consent),'reopening consent sends no request or notification');
SELECT correction_assert((SELECT status='cancelled' FROM notification_outbox WHERE idempotency_key='OLD-REMINDER'),'old manual or pending agreement request is cancelled');
SELECT correction_assert((SELECT before_data->>'feu_vert'='autorise' AND after_data->>'consent_request_version'='1' FROM audit_actions WHERE action='correction_accord'),'agreement audit preserves old decision and new generation');
SELECT correction_reject($q$SELECT queue_message('ca300000-0000-4000-8000-000000000001','Nouvelle demande','demande_feu_vert','missing-version',NULL,'telegram')$q$,'renewed request requires preview generation','40001');
SELECT correction_reject($q$SELECT queue_message('ca300000-0000-4000-8000-000000000001','Ancien aperçu','demande_feu_vert','stale-preview',NULL,'telegram',0)$q$,'old preview cannot send new generation','40001');
SELECT queue_message('ca300000-0000-4000-8000-000000000001','Nouvelle demande volontaire','demande_feu_vert','CURRENT-REQUEST',NULL,'telegram',1);
SELECT correction_assert((SELECT request_snapshot->>'consent_request_version'='1' AND request_snapshot ? 'invoice_requested' FROM messages WHERE texte='Nouvelle demande volontaire'),'manual request snapshots current generation and invoice metadata');
SELECT queue_message('ca300000-0000-4000-8000-000000000001','Rappel même accord','relance_feu_vert','CURRENT-REMINDER',NULL,'telegram',1);
SELECT correction_assert((SELECT consent_request_version=1 FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'reminder never creates a new agreement generation');
RESET ROLE;
UPDATE messages SET telegram_msg_id='CURRENT-MESSAGE' WHERE texte='Nouvelle demande volontaire';
UPDATE colis SET statut='attente_feu_vert' WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT correction_reject($q$SELECT telegram_client_decision('ca300000-0000-4000-8000-000000000001','approve','CHAT-CORRECTION','OLD-COMBINED')$q$,'old Telegram button stays invalid for identical composition','40001');
SELECT set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','ca000000-0000-4000-8000-000000000003',true);
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT client_decision('ca300000-0000-4000-8000-000000000001','approve')$q$,'portal cannot bypass renewed agreement CAS','40001');
SELECT correction_assert((SELECT consent_request_version=1 AND devis_total IS NULL AND payplug_payment_url IS NULL FROM client_colis WHERE id='ca300000-0000-4000-8000-000000000001'),'safe client view exposes generation and conceals withdrawn commercial values');
