SELECT correction_assert((SELECT feu_vert='autorise' AND consent_request_version=1 FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'current Telegram request accepts current agreement');
-- A→B→A identity changes never revive the first button.
UPDATE colis SET trackings=ARRAY['RECEIPT-2'] WHERE id='ca300000-0000-4000-8000-000000000001';
UPDATE colis SET trackings=ARRAY['RECEIPT-1'] WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT correction_assert((SELECT consent_request_version=3 FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'),'each carton identity change increments generation even when composition returns');
SELECT correction_reject($q$SELECT telegram_client_decision('ca300000-0000-4000-8000-000000000001','approve','CHAT-CORRECTION','CURRENT-MESSAGE')$q$,'restoring carton identity does not revive old buttons','40001');
SELECT set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','ca000000-0000-4000-8000-000000000002',true);
