SELECT correction_reject($q$SELECT queue_message('ca300000-0000-4000-8000-000000000001','Nouveau rappel','demande_feu_vert','CURRENT-REQUEST',NULL,'telegram',3)$q$,'old idempotency key cannot masquerade as new consent','40001');
