SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'accord','{}',updated_at,'Nouvel accord') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'archived dossier is frozen','22023');
RESET ROLE;
UPDATE colis SET archive=false,paiement_date=now(),paiement_montant=120 WHERE id='ca300000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'accord','{}',updated_at,'Nouvel accord') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'paid dossier is frozen','22023');
RESET ROLE;
UPDATE colis SET paiement_date=NULL,paiement_montant=NULL,date_expedition=now() WHERE id='ca300000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'accord','{}',updated_at,'Nouvel accord') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'physically dispatched dossier is frozen','22023');
RESET ROLE;
UPDATE colis SET date_expedition=NULL WHERE id='ca300000-0000-4000-8000-000000000001';
INSERT INTO envois(id,destination_code,date_depart,statut) VALUES('ca500000-0000-4000-8000-000000000001','974',current_date,'planifie');
UPDATE colis SET envoi_id='ca500000-0000-4000-8000-000000000001' WHERE id='ca300000-0000-4000-8000-000000000001';
SELECT set_config('expedile.confirm_departure','allowed',true);
UPDATE envois SET departed_at=now(),manifest_version=1 WHERE id='ca500000-0000-4000-8000-000000000001';
SELECT set_config('expedile.confirm_departure','',true);
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'accord','{}',updated_at,'Nouvel accord') FROM colis WHERE id='ca300000-0000-4000-8000-000000000001'$q$,'committed departure manifest freezes dossier even before local status catches up','22023');
RESET ROLE;
-- A historical registry entry can acquire cancellation proof, but no quote data can be rewritten.
INSERT INTO colis(id,client_id,ref,statut,feu_vert,devis_total,devis_brouillon,payplug_payment_id,payplug_payment_url)
 VALUES('ca300000-0000-4000-8000-000000000002','ca200000-0000-4000-8000-000000000001','EXP-CANCELLEGACY','devis_envoye','autorise',100,false,'pay_cancelLegacy','https://example.test/legacy');
ALTER TABLE legacy_payplug_payments DISABLE TRIGGER guard_legacy_payplug_snapshot;
INSERT INTO legacy_payplug_payments(provider_id,colis_id,client_id,colis_ref,amount_cents,billing_email,quote_snapshot)
 SELECT payplug_payment_id,id,client_id,ref,10000,'legacy-correction@example.test',_legacy_payplug_quote_snapshot(c) FROM colis c WHERE id='ca300000-0000-4000-8000-000000000002';
ALTER TABLE legacy_payplug_payments ENABLE TRIGGER guard_legacy_payplug_snapshot;
SET LOCAL ROLE authenticated;
SELECT correction_reject($q$SELECT correct_colis_task(id,'accord','{}',updated_at,'Nouvel accord') FROM colis WHERE id='ca300000-0000-4000-8000-000000000002'$q$,'legacy hosted link must also be cancelled before correction','22023');
RESET ROLE;
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT record_payplug_cancellation(colis_id,provider_id,jsonb_build_object('object','payment','id',provider_id,'is_paid',false,'failure',jsonb_build_object('code','aborted'),'currency','EUR','amount',amount_cents,'is_live',true,'metadata',jsonb_build_object('colis_id',colis_id,'colis_ref',colis_ref),'billing',jsonb_build_object('email',billing_email))) FROM legacy_payplug_payments WHERE provider_id='pay_cancelLegacy';
SELECT correction_assert((SELECT provider_cancelled_at IS NOT NULL AND quote_snapshot=_legacy_payplug_quote_snapshot(c) FROM legacy_payplug_payments l JOIN colis c ON c.id=l.colis_id WHERE provider_id='pay_cancelLegacy'),'legacy cancellation proof does not mutate immutable snapshot');
SELECT correction_reject($q$UPDATE legacy_payplug_payments SET provider_cancelled_at=NULL WHERE provider_id='pay_cancelLegacy'$q$,'legacy cancellation proof cannot be erased');
SELECT set_config('request.jwt.claim.role','authenticated',true);
SET LOCAL ROLE authenticated;
SELECT correct_colis_task(id,'accord','{}',updated_at,'Nouvel accord après annulation lien') FROM colis WHERE id='ca300000-0000-4000-8000-000000000002';
SELECT correction_assert((SELECT payplug_payment_id IS NULL AND payplug_payment_url IS NULL AND consent_request_version=1 FROM colis WHERE id='ca300000-0000-4000-8000-000000000002'),'cancelled legacy link can be retired through explicit correction');
ROLLBACK;
